<?php
require_once __DIR__.'/BusinessHubService.php';
require_once __DIR__.'/../SocialMedia/SocialMonthlyPlanService.php';
require_once __DIR__.'/../../Jobs/SocialMonthlyRecurringJob.php';
/** Explicitly budgeted recurring drafts; each new month still requires human publication approval. */
class SocialRecurringService
{
    private $db;private PDO $pdo;
    public function __construct(?Database $db=null){$this->db=$db??Database::getInstance();$this->pdo=$this->db->getConnection();}
    private function q(string $sql,array $args=[]): PDOStatement{$s=$this->pdo->prepare($sql);$s->execute($args);return $s;}
    private function ready(): void{if(!(new BusinessHubService($this->db))->has('social_monthly_autopilot'))throw new InvalidArgumentException('Install the Business Hub SQL update');}
    public static function nextMonth(string $source,string $timezone,?DateTimeImmutable $now=null): string{$tz=new DateTimeZone($timezone);$now=($now??new DateTimeImmutable('now',$tz))->setTimezone($tz);if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$source))throw new InvalidArgumentException('Invalid source month');$from=(new DateTimeImmutable($source.'-01',$tz))->modify('+1 month');$next=$now->modify('first day of next month')->setTime(0,0);return max($from->format('Y-m'),$next->format('Y-m'));}
    public function policy(int $uid,int $wid): ?array{if(!(new BusinessHubService($this->db))->has('social_monthly_autopilot'))return null;$r=$this->q('SELECT enabled,version,source_plan_id,max_cycle_price,next_month,next_due_at,last_plan_id,last_error FROM social_monthly_autopilot WHERE user_id=? AND website_id=?',[$uid,$wid])->fetch(PDO::FETCH_ASSOC);return $r?:null;}
    public function configure(int $uid,int $wid,array $input): array{
        $this->ready();(new BusinessHubService($this->db))->profile($uid,$wid);$enable=($input['enabled']??false)===true;
        if(!ExternalExecution::lock('social-recurring:'.$wid))throw new RuntimeException('Recurring configuration busy');
        try{if(!$enable){$this->q('UPDATE social_monthly_autopilot SET enabled=0,version=version+1,next_due_at=NULL,updated_at=UTC_TIMESTAMP() WHERE website_id=? AND user_id=?',[$wid,$uid]);return ['policy'=>$this->policy($uid,$wid)];}
            if(($input['cost_confirmed']??false)!==true)throw new InvalidArgumentException('Confirm monthly generation usage and review-before-publication policy');
            if(!SocialMonthlyPlanService::worker()['ready'])throw new InvalidArgumentException('Enable the publishing worker first');$cap=$input['max_cycle_price']??0;if(!is_numeric($cap)||!is_finite((float)$cap)||(float)$cap<0||(float)$cap>100)throw new InvalidArgumentException('Invalid generation cost ceiling');
            $p=$this->q("SELECT * FROM social_monthly_plans WHERE id=? AND website_id=? AND user_id=? AND status IN ('active','completed') AND approved_at IS NOT NULL",[(int)($input['source_plan_id']??0),$wid,$uid])->fetch(PDO::FETCH_ASSOC);if(!$p)throw new InvalidArgumentException('Choose an approved active or completed plan for this website');$brief=json_decode($p['brief_json'],true);(new BusinessHubService($this->db))->assertRevision($uid,$wid,$brief);
            if(empty($brief['shared_profile']))throw new InvalidArgumentException('Prepare and approve a plan using the shared company profile first');
            $this->q('INSERT INTO social_monthly_autopilot(website_id,user_id,source_plan_id,enabled,max_cycle_price,updated_at) VALUES(?,?,?,1,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE source_plan_id=VALUES(source_plan_id),enabled=1,max_cycle_price=VALUES(max_cycle_price),version=version+1,last_error=NULL,updated_at=UTC_TIMESTAMP()',[$wid,$uid,$p['id'],round((float)$cap,2)]);
            $this->schedule($uid,$wid,self::nextMonth($brief['month'],$brief['timezone']),$brief['timezone']);return ['policy'=>$this->policy($uid,$wid)];
        }finally{ExternalExecution::unlock('social-recurring:'.$wid);}
    }
    private function schedule(int $uid,int $wid,string $month,string $timezone): void{
        $policy=$this->policy($uid,$wid);if(!$policy||!$policy['enabled'])return;$due=(new DateTimeImmutable($month.'-01',new DateTimeZone($timezone)))->modify('-1 month')->modify('+19 days')->setTime(9,0); // 20th before target month, local time.
        $at=max(time()+1,$due->getTimestamp());$payload=['user_id'=>$uid,'website_id'=>$wid,'month'=>$month,'policy_version'=>(int)$policy['version']];$pending=$this->q("SELECT id FROM jobs WHERE job_class='SocialMonthlyRecurringJob' AND payload=? AND status='pending' LIMIT 1",[json_encode($payload)])->fetchColumn();if(!$pending){$pending=(new QueueManager($this->db))->push(SocialMonthlyRecurringJob::class,$payload,'social',max(1,$at-time()));if(!$pending)throw new RuntimeException('Recurring queue unavailable');$this->q('UPDATE jobs SET available_at=? WHERE id=?',[gmdate('Y-m-d H:i:s',$at),$pending]);}
        $this->q('UPDATE social_monthly_autopilot SET next_month=?,next_due_at=?,updated_at=UTC_TIMESTAMP() WHERE website_id=? AND user_id=?',[$month,gmdate('Y-m-d H:i:s',$at),$wid,$uid]);
    }
    public function run(array $payload): void{
        $this->ready();$uid=(int)($payload['user_id']??0);$wid=(int)($payload['website_id']??0);if(!ExternalExecution::lock('social-recurring:'.$wid))throw new RuntimeException('Recurring cycle busy');
        try{$cfg=$this->policy($uid,$wid);if(!$cfg||!$cfg['enabled']||(int)$cfg['version']!==(int)($payload['policy_version']??0))return;if(!empty($cfg['last_plan_id'])){$last=$this->q('SELECT status,approved_at FROM social_monthly_plans WHERE id=? AND user_id=? AND website_id=?',[$cfg['last_plan_id'],$uid,$wid])->fetch(PDO::FETCH_ASSOC);if(!$last||empty($last['approved_at'])||!in_array($last['status'],['active','completed'],true))throw new InvalidArgumentException('Review and approve the previously generated monthly plan before another automatic draft');}$month=(string)($payload['month']??'');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$month))throw new InvalidArgumentException('Invalid scheduled month');
            $p=$this->q('SELECT brief_json,timezone FROM social_monthly_plans WHERE id=? AND user_id=? AND website_id=?',[$cfg['source_plan_id'],$uid,$wid])->fetch(PDO::FETCH_ASSOC);if(!$p)throw new InvalidArgumentException('Source plan unavailable');$localNow=new DateTimeImmutable('now',new DateTimeZone($p['timezone']));if($month<=$localNow->format('Y-m')){$this->schedule($uid,$wid,$localNow->modify('first day of next month')->format('Y-m'),$p['timezone']);return;}$input=json_decode($p['brief_json'],true);(new BusinessHubService($this->db))->assertRevision($uid,$wid,$input);
            $requestKey='recurring_'.$wid.'_'.str_replace('-','',$month);$prior=$this->q('SELECT id,status FROM social_monthly_plans WHERE user_id=? AND website_id=? AND request_key=?',[$uid,$wid,$requestKey])->fetch(PDO::FETCH_ASSOC);if($prior){if($prior['status']==='failed')throw new InvalidArgumentException('Previous monthly generation failed. Review its outcome before retrying');$result=(new SocialMonthlyPlanService($this->db))->detail($uid,(int)$prior['id']);}else{$quote=PlanUsage::check($uid,'marketing_tool','marketing_tool','Allowance unavailable');if(empty($quote['ok'])||(($quote['source']??'')==='wallet'&&(float)$quote['price']>(float)$cfg['max_cycle_price']))throw new InvalidArgumentException('Monthly generation stopped: review balance, allowance or price ceiling');
            $input['website_id']=$wid;$input['month']=$month;$input['request_key']=$requestKey;$input['quote_hash']=SocialMonthlyPlanService::quoteHash($quote);$result=(new SocialMonthlyPlanService($this->db))->create($uid,$input);}
            $this->q('UPDATE social_monthly_autopilot SET last_plan_id=?,last_error=NULL,updated_at=UTC_TIMESTAMP() WHERE website_id=? AND user_id=?',[$result['plan']['id'],$wid,$uid]);
            $next=(new DateTimeImmutable($month.'-01',new DateTimeZone($p['timezone'])))->modify('+1 month')->format('Y-m');$this->schedule($uid,$wid,$next,$p['timezone']);
        }catch(Throwable $e){$this->q('UPDATE social_monthly_autopilot SET enabled=0,last_error=?,next_due_at=NULL,updated_at=UTC_TIMESTAMP() WHERE website_id=? AND user_id=?',[mb_substr($e instanceof InvalidArgumentException?$e->getMessage():'Monthly generation paused; review worker, source plan and outcome before enabling again',0,500),$wid,$uid]);try{Notification::notify($uid,'social_monthly_attention','Monthly social generation needs review','Review the company hub before enabling generation again.','/business-hub');}catch(Throwable $ignored){}}
        finally{ExternalExecution::unlock('social-recurring:'.$wid);}
    }
}
